package com.desktodo.app;
import android.app.*;import android.os.*;import android.graphics.*;import org.json.*;import java.io.*;import java.util.*;
/** Debug-only isolated model/renderer checks; does not modify user tasks or screen. */
public final class DeskChecks extends Instrumentation {
 Bundle args;
 @Override public void onCreate(Bundle b){args=b;start();}
 void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 @Override public void onStart(){Bundle result=new Bundle();try{
  check(DeskModel.movement(1.25).equals("▲ +1.25%"),"positive sign");check(DeskModel.movement(-1.25).equals("▼ -1.25%"),"negative sign");check(DeskModel.movement(0).equals("— 0.00%"),"flat sign");
  check(DeskModel.symbols("sh600519,usAAPL").length()==2,"symbol parse");boolean rejected=false;try{DeskModel.symbols("sh600519,sh600519");}catch(Exception e){rejected=true;}check(rejected,"duplicate symbols rejected");rejected=false;try{DeskModel.normalizeOrigin("http://user:pass@192.168.1.1");}catch(Exception e){rejected=true;}check(rejected,"credentials in device URL rejected");
  JSONArray fixture=new JSONArray().put(DeskModel.task("普通事项",null)).put(DeskModel.task("置顶事项",null).put("pinned",true));check(DeskModel.ordered(fixture).getJSONObject(0).getString("title").equals("置顶事项"),"pinned ordering");check(fixture.getJSONObject(0).getString("title").equals("普通事项"),"ordering does not mutate source");
  JSONArray device=new JSONArray().put(DeskModel.task("device",null));JSONArray local=DeskModel.copy(device);local.getJSONObject(0).put("title","edited").put("pinned",true);local.put(DeskModel.task("added",null));check(device.length()==1&&device.getJSONObject(0).getString("title").equals("device")&&!device.getJSONObject(0).optBoolean("pinned"),"local edits must not mutate device baseline");local.remove(0);check(device.length()==1,"local deletion must not mutate device baseline");
  EditRevision revisions=new EditRevision();revisions.edited();long first=revisions.snapshot();revisions.edited();check(!revisions.acknowledge(first),"old sync reply must not clear newer local edits");long second=revisions.snapshot();check(revisions.acknowledge(second),"latest sync reply clears pending edits");check(!revisions.acknowledge(first),"older reply after newest acknowledgement must be rejected");revisions.edited();check(!revisions.acknowledge(first),"late stale reply cannot clear deletion or restore");check(revisions.acknowledge(revisions.snapshot()),"latest removal/restore revision acknowledged");
  JSONObject baseline=new JSONObject().put("layout_id","mac.overview.red-v2.phone").put("tasks",new JSONArray().put(DeskModel.task("original",null)));
  JSONArray edited=DeskModel.copy(baseline.getJSONArray("tasks"));edited.getJSONObject(0).put("title","offline edit");JSONObject unchanged=DeskModel.copy(baseline);
  check(SyncPolicy.recovery(baseline,unchanged,edited,true)==SyncPolicy.Recovery.RETRY,"retry local edit only when device baseline unchanged");
  JSONObject committed=DeskModel.copy(baseline).put("tasks",DeskModel.copy(edited));check(SyncPolicy.recovery(baseline,committed,edited,true)==SyncPolicy.Recovery.ACKNOWLEDGED,"lost success response recognized without duplicate write");
  JSONObject concurrent=DeskModel.copy(baseline);concurrent.getJSONArray("tasks").getJSONObject(0).put("title","other client");check(SyncPolicy.recovery(baseline,concurrent,edited,true)==SyncPolicy.Recovery.CONFLICT,"other client changes never overwritten automatically");
  check(SyncPolicy.recovery(baseline,DeskModel.copy(committed).put("layout_id","mac.focus.red-v2"),edited,true)==SyncPolicy.Recovery.CONFLICT,"different layout requires user choice");check(SyncPolicy.recovery(baseline,concurrent,edited,false)==SyncPolicy.Recovery.CLEAN,"clean client can read new device state");
  JSONArray keyOrderA=new JSONArray("[{\"id\":\"a\",\"title\":\"A\"},{\"id\":\"b\",\"title\":\"B\"}]");JSONArray keyOrderB=new JSONArray("[{\"title\":\"B\",\"id\":\"b\"},{\"title\":\"A\",\"id\":\"a\"}]");check(SyncPolicy.sameTasks(keyOrderA,keyOrderB),"JSON key/task transport order is not a conflict");keyOrderB.getJSONObject(0).put("title","changed");check(!SyncPolicy.sameTasks(keyOrderA,keyOrderB),"actual task mutation remains a conflict");
  check(SyncPolicy.retryDelay(1)==5000&&SyncPolicy.retryDelay(2)==10000&&SyncPolicy.retryDelay(9)==60000,"bounded write retry backoff");check(SyncPolicy.frameChanged(baseline,DeskModel.copy(baseline).put("content_key","new")),"new non-task information refreshes preview");
  String[] kinds={"focus","agenda","minimal","overview","pomodoro","living","custom"};
  for(String kind:kinds){JSONObject cfg=DeskModel.defaults().put("layout",kind);String id=DeskModel.layoutId(cfg);byte[] initial=new byte[48000];Arrays.fill(initial,(byte)255);initial[20*100+90]=0;initial[449*100+95]=0;
   DeskRenderer one=new DeskRenderer(initial,new JSONArray().put(DeskModel.task("测试事项",null)),cfg,null,new JSONArray());one.tasks(id);byte[] before=one.frame();DeskRenderer empty=new DeskRenderer(before,new JSONArray(),cfg,null,new JSONArray());empty.tasks(id);byte[] after=empty.frame();int oldInk=0,newInk=0;for(int y=160;y<180;y++)for(int x=24;x<450;x++){int at=y*100+x/8,mask=128>>(x%8);if((before[at]&mask)==0)oldInk++;if((after[at]&mask)==0)newInk++;}check(oldInk>0,kind+" first-row content present");check(newInk==0,kind+" completion clears first row");check(after[20*100+90]==0&&after[449*100+95]==0,kind+" weather and stock preserved");
   int width=kind.equals("minimal")?752:kind.equals("focus")||kind.equals("agenda")?500:kind.equals("pomodoro")?430:kind.equals("custom")?(int)Math.floor(752*.67/8)*8-24:478;int top=kind.equals("minimal")?150:118,bottom=kind.equals("custom")?456:404;
   for(int i=0;i<48000;i++){int px=(i%100)*8,y=i/100;boolean allowed=px+8>24&&px<24+width&&y>=top&&y<bottom||kind.equals("pomodoro")&&px+8>510&&px<770&&y>=348&&y<402;check(allowed||before[i]==after[i],kind+" unchanged module at "+i);if(y>=80&&y<104)check(after[i]==(byte)255,kind+" red reserved band");}
   DeskRenderer full=new DeskRenderer(initial,fixture,cfg,null,new JSONArray());full.full(id);byte[] fullFrame=full.frame();check(fullFrame.length==48000,"frame length");check(Arrays.equals(DeskRenderer.pack(DeskRenderer.decode(fullFrame)),fullFrame),"bitmap round trip");if(kind.equals("overview")){try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),"android-overview-preview.png"))){full.image.compress(Bitmap.CompressFormat.PNG,100,out);}}
  }
  check(DeskModel.contentKey("same").equals(DeskModel.contentKey("same")),"stable persistence key");check(!DeskModel.contentKey("same").equals(DeskModel.contentKey("changed")),"changed content persistence key");
  if(args!=null&&"1".equals(args.getString("feeds"))){JSONObject settings=new JSONObject(getTargetContext().getSharedPreferences("mojian-native",0).getString("cfg",DeskModel.defaults().toString()));check(DeskApi.weather(settings).getJSONObject("current").has("temperature_2m"),"live phone weather");check(DeskApi.stocks(settings.getJSONArray("stocks")).length()==settings.getJSONArray("stocks").length(),"live phone stocks");}
  if(args!=null&&args.containsKey("device")){String origin=DeskModel.normalizeOrigin(args.getString("device"));check(DeskApi.state(origin).has("tasks"),"live device state");check(DeskApi.base(origin).length==48000,"live device base");}
  result.putString("stream","PASS: native sign/symbol validation, pinned ordering, seven layout removal/preservation, red band, bitmap round-trip and optional read-only device checks\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("stream","FAIL: "+e.toString()+"\n");finish(Activity.RESULT_CANCELED,result);}}
}
